'use strict';

const EQUAL = 0;
const DELETE = 1;
const INSERT = 2;
const OP_NAMES = ['equal', 'delete', 'insert'];

function assertLines(value, name) {
  if (!Array.isArray(value)) throw new TypeError(`${name} must be an array of strings`);
  for (let i = 0; i < value.length; i++) {
    if (typeof value[i] !== 'string') throw new TypeError(`${name}[${i}] must be a string`);
  }
}

/**
 * Find a split point on a minimal edit path between A[aLo, aHi) and B[bLo, bHi)
 * using Myers' linear-space bidirectional search (middle snake). Both ranges are
 * nonempty with no common prefix/suffix, so the edit distance is at least 2 and
 * both halves of the split have strictly smaller edit distance.
 * Returns [x, y] relative to (aLo, bLo).
 */
function bisect(A, B, aLo, aHi, bLo, bHi) {
  const len1 = aHi - aLo;
  const len2 = bHi - bLo;
  const maxD = Math.ceil((len1 + len2) / 2);
  const vOffset = maxD + 1;
  const vLength = 2 * maxD + 3;
  const v1 = new Int32Array(vLength).fill(-1);
  const v2 = new Int32Array(vLength).fill(-1);
  v1[vOffset + 1] = 0;
  v2[vOffset + 1] = 0;
  const delta = len1 - len2;
  const front = (delta & 1) !== 0;
  let k1start = 0;
  let k1end = 0;
  let k2start = 0;
  let k2end = 0;

  for (let d = 0; d <= maxD; d++) {
    // Forward search.
    for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
      const k1Offset = vOffset + k1;
      let x1;
      if (k1 === -d || (k1 !== d && v1[k1Offset - 1] < v1[k1Offset + 1])) {
        x1 = v1[k1Offset + 1];
      } else {
        x1 = v1[k1Offset - 1] + 1;
      }
      let y1 = x1 - k1;
      while (x1 < len1 && y1 < len2 && A[aLo + x1] === B[bLo + y1]) {
        x1++;
        y1++;
      }
      v1[k1Offset] = x1;
      if (x1 > len1) {
        k1end += 2;
      } else if (y1 > len2) {
        k1start += 2;
      } else if (front) {
        const k2Offset = vOffset + delta - k1;
        if (k2Offset >= 0 && k2Offset < vLength && v2[k2Offset] !== -1) {
          if (x1 >= len1 - v2[k2Offset]) return [x1, y1];
        }
      }
    }

    // Reverse search.
    for (let k2 = -d + k2start; k2 <= d - k2end; k2 += 2) {
      const k2Offset = vOffset + k2;
      let x2;
      if (k2 === -d || (k2 !== d && v2[k2Offset - 1] < v2[k2Offset + 1])) {
        x2 = v2[k2Offset + 1];
      } else {
        x2 = v2[k2Offset - 1] + 1;
      }
      let y2 = x2 - k2;
      while (x2 < len1 && y2 < len2 && A[aHi - 1 - x2] === B[bHi - 1 - y2]) {
        x2++;
        y2++;
      }
      v2[k2Offset] = x2;
      if (x2 > len1) {
        k2end += 2;
      } else if (y2 > len2) {
        k2start += 2;
      } else if (!front) {
        const k1Offset = vOffset + delta - k2;
        if (k1Offset >= 0 && k1Offset < vLength && v1[k1Offset] !== -1) {
          const x1 = v1[k1Offset];
          const y1 = x1 - (k1Offset - vOffset);
          if (x1 >= len1 - x2) return [x1, y1];
        }
      }
    }
  }
  throw new Error('internal error: diff search did not converge');
}

/** Append edit codes for A[aLo, aHi) -> B[bLo, bHi) to codes. */
function diffRange(A, B, aLo, aHi, bLo, bHi, codes) {
  while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) {
    codes.push(EQUAL);
    aLo++;
    bLo++;
  }
  let suffix = 0;
  while (aHi > aLo && bHi > bLo && A[aHi - 1] === B[bHi - 1]) {
    aHi--;
    bHi--;
    suffix++;
  }
  if (aLo === aHi) {
    for (let j = bLo; j < bHi; j++) codes.push(INSERT);
  } else if (bLo === bHi) {
    for (let i = aLo; i < aHi; i++) codes.push(DELETE);
  } else {
    const [x, y] = bisect(A, B, aLo, aHi, bLo, bHi);
    diffRange(A, B, aLo, aLo + x, bLo, bLo + y, codes);
    diffRange(A, B, aLo + x, aHi, bLo + y, bHi, codes);
  }
  for (let s = 0; s < suffix; s++) codes.push(EQUAL);
}

/**
 * Minimal edit codes for a -> b with every maximal non-equal region ordered as
 * all deletes followed by all inserts.
 */
function editCodes(a, b) {
  const ids = new Map();
  const intern = (line) => {
    let id = ids.get(line);
    if (id === undefined) {
      id = ids.size;
      ids.set(line, id);
    }
    return id;
  };
  const A = new Int32Array(a.length);
  const B = new Int32Array(b.length);
  for (let i = 0; i < a.length; i++) A[i] = intern(a[i]);
  for (let j = 0; j < b.length; j++) B[j] = intern(b[j]);

  const raw = [];
  diffRange(A, B, 0, a.length, 0, b.length, raw);

  const codes = new Uint8Array(raw.length);
  let out = 0;
  let k = 0;
  while (k < raw.length) {
    if (raw[k] === EQUAL) {
      codes[out++] = EQUAL;
      k++;
      continue;
    }
    let dels = 0;
    let ins = 0;
    while (k < raw.length && raw[k] !== EQUAL) {
      if (raw[k] === DELETE) dels++;
      else ins++;
      k++;
    }
    codes.fill(DELETE, out, out + dels);
    out += dels;
    codes.fill(INSERT, out, out + ins);
    out += ins;
  }
  return codes;
}

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
