  if (!Number.isSafeInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);
  const n = script.length;

  // Old/new line counts consumed before each script index.
  const oldBefore = new Int32Array(n + 1);
  const newBefore = new Int32Array(n + 1);
  for (let k = 0; k < n; k++) {
    const op = script[k].op;
    oldBefore[k + 1] = oldBefore[k] + (op === 'insert' ? 0 : 1);
    newBefore[k + 1] = newBefore[k] + (op === 'delete' ? 0 : 1);
  }

  const hunks = [];
  let k = 0;
  while (k < n) {
    if (script[k].op === 'equal') {
      k++;
      continue;
    }
    const firstChange = k;
    let lastChangeEnd = k; // exclusive end of the last change region in this hunk
    while (true) {
      while (lastChangeEnd < n && script[lastChangeEnd].op !== 'equal') lastChangeEnd++;
      let next = lastChangeEnd;
      while (next < n && script[next].op === 'equal') next++;
      if (next < n && next - lastChangeEnd <= 2 * context) {
        lastChangeEnd = next;
      } else {
        break;
      }
    }
    const start = Math.max(0, firstChange - context);
    const end = Math.min(n, lastChangeEnd + context);

    const lines = new Array(end - start);
    for (let t = start; t < end; t++) {
      const entry = script[t];
      const prefix = entry.op === 'equal' ? ' ' : entry.op === 'delete' ? '-' : '+';
      lines[t - start] = prefix + entry.line;
    }
    const oldLines = oldBefore[end] - oldBefore[start];
    const newLines = newBefore[end] - newBefore[start];
    hunks.push({
      oldStart: oldLines === 0 ? oldBefore[start] : oldBefore[start] + 1,
      oldLines,
      newStart: newLines === 0 ? newBefore[start] : newBefore[start] + 1,
      newLines,
      lines,
    });
    k = end;
  }
  return hunks;
}

function isCount(value) {
  return Number.isSafeInteger(value) && value >= 0;
