/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  assertLines(a, 'a');
  if (!Array.isArray(hunks)) throw new TypeError('hunks must be an array');

  const result = [];
  let consumed = 0; // number of original lines already copied or removed

  for (let h = 0; h < hunks.length; h++) {
    const fail = (reason) => {
      throw new Error(`hunk ${h} does not apply: ${reason}`);
    };
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!isCount(oldStart) || !isCount(oldLines) || !isCount(newStart) || !isCount(newLines)) {
      fail('starts and counts must be nonnegative integers');
    }
    if (!Array.isArray(lines) || lines.length === 0) fail('lines must be a nonempty array');

    let oldCount = 0;
    let newCount = 0;
    for (let t = 0; t < lines.length; t++) {
      const line = lines[t];
      if (typeof line !== 'string' || line.length === 0) fail(`line ${t} is malformed`);
      const prefix = line[0];
      if (prefix === ' ') {
        oldCount++;
        newCount++;
      } else if (prefix === '-') {
        oldCount++;
      } else if (prefix === '+') {
        newCount++;
      } else {
        fail(`line ${t} has invalid prefix`);
      }
    }
    if (oldCount !== oldLines) fail(`oldLines is ${oldLines} but lines contain ${oldCount}`);
    if (newCount !== newLines) fail(`newLines is ${newLines} but lines contain ${newCount}`);

    let pos;
    if (oldLines === 0) {
      pos = oldStart;
    } else {
      if (oldStart === 0) fail('oldStart must be at least 1 for a nonempty old range');
      pos = oldStart - 1;
    }
    if (pos < consumed) fail('overlaps or precedes an earlier hunk');
    if (pos + oldLines > a.length) fail('old range extends past the end of the input');

    const newPos = result.length + (pos - consumed);
    const expectedNewStart = newLines === 0 ? newPos : newPos + 1;
    if (newStart !== expectedNewStart) {
      fail(`newStart is ${newStart} but expected ${expectedNewStart}`);
    }

    // Verify before producing any output for this hunk.
    let i = pos;
    for (let t = 0; t < lines.length; t++) {
      const line = lines[t];
      if (line[0] === '+') continue;
      if (a[i] !== line.slice(1)) fail(`line ${t} does not match original line ${i + 1}`);
      i++;
    }

    for (let r = consumed; r < pos; r++) result.push(a[r]);
    for (let t = 0; t < lines.length; t++) {
      const line = lines[t];
      if (line[0] !== '-') result.push(line.slice(1));
    }
    consumed = pos + oldLines;
  }

  for (let r = consumed; r < a.length; r++) result.push(a[r]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

